Object.assign(D.ru,{hero:'Как изменилась походка ребёнка?',desc:'Сравните исходную ходьбу с устными подсказками и VR.',gpsTitle:'Общее отклонение походки (GPS)',gpsHint:'Снижение GPS означает приближение к референсному паттерну. Это не доказательство клинического улучшения.',gpsMissing:'Столбец GPS не найден или значений недостаточно.',closer:'Ближе к референсу',farther:'Дальше от референса',unchanged:'Без изменений',important:'Автоматический анализ: важные изменения',rankHint:'Изменение делится на исходное стандартное отклонение и ранжируется по модулю (минимум 3 значения). Это не клиническая значимость.',score:'Стандартизированное изменение',absolute:'Абсолютное изменение',anomaly:'Необычные шаги',anomalyHint:'Внутри каждого условия: отклонение от медианы более 3,5 робастных стандартных отклонений. Нужно минимум 5 значений и ненулевой MAD. Специалист проверяет шаги; автоматически они не удаляются.',noneFlag:'По этому правилу необычных значений не найдено (или данных недостаточно).',cycle:'Цикл шага',value:'Значение',onePage:'Одностраничный отчёт / PDF',shortReport:'Краткий отчёт для врача',rankEmpty:'Недостаточно данных для сравнения.',flagCount:'Число отмеченных значений',gpsPartial:'Недостаточно данных для сравнения двух условий.',gpsTrade:'Проверьте отдельные суставные показатели: GPS не описывает все изменения.'});
function gpsKey(){return cols().find(([k])=>['gpsa','gps','gpsscore','gpsdeg','gpsdegrees','gaitprofilescore','gaitprofilescoredeg','gaitprofilescoredegrees'].includes(k))?.[0]}
function signed(x){return valid(x)?(x>0?'+':'')+num(x):'—'}
function gpsResults(){let k=gpsKey();if(!k)return [];let b=stat(C[0],sid,k);return C.slice(1).map((c,i)=>{let a=stat(c,sid,k),d=delta(b.m,a.m);return {i:i+1,b,a,d,label:valid(d)?t(d<0?'closer':d>0?'farther':'unchanged'):t('gpsPartial')}})}
function gpsPanel(){let r=gpsResults();return `<div class="card"><h2>${E(t('gpsTitle'))}</h2><p class="small">${E(t('gpsHint'))}</p>${!r.length?`<p>${E(t('gpsMissing'))}</p>`:`<div class="grid two">${r.map(x=>`<div class="mini"><span>${E(cond(x.i))}</span><strong>${signed(x.d)}${valid(x.d)?'°':''}</strong><span>${E(x.label)}</span><div class="small">${num(x.b.m)} → ${num(x.a.m)} · n=${x.b.n}/${x.a.n}</div></div>`).join('')}</div>`}<p class="small">${E(t('gpsTrade'))}</p></div>`}
function median(a){let b=[...a].sort((x,y)=>x-y),i=Math.floor(b.length/2);return b.length?(b.length%2?b[i]:(b[i-1]+b[i])/2):NaN}
function unusual(){let out=[];for(let c of C)for(let [k,h] of cols()){let a=rows(c,sid).filter(r=>valid(r.vals[k])),v=a.map(r=>r.vals[k]);if(v.length<5)continue;let m=median(v),mad=median(v.map(x=>Math.abs(x-m)));if(!(mad>0))continue;for(let r of a){let z=Math.abs(r.vals[k]-m)*.67448975/mad;if(z>3.5)out.push({c,k,h,cyc:r.cyc,value:r.vals[k],z})}}return out.sort((a,b)=>b.z-a.z)}
function anomalyPanel(){let a=unusual();return `<div class="card"><h2>${E(t('anomaly'))} · ${a.length}</h2><p class="small">${E(t('anomalyHint'))}</p>${a.length?`<div class="table"><table><thead><tr><th>${E(t('parameter'))}</th><th>${E(t('cycle'))}</th><th>${E(t('value'))}</th><th>MAD-z</th></tr></thead><tbody>${a.map(x=>`<tr><td>${E(x.c)} · ${E(label(x.k,x.h))}</td><td>${E(x.cyc)}</td><td>${num(x.value)}</td><td>${num(x.z)}</td></tr>`).join('')}</tbody></table></div>`:`<p>${E(t('noneFlag'))}</p>`}</div>`}
function shortReport(){let r=gpsResults(),a=reportItems(),u=unusual(),html=`<div id="print-report"><h1>Asyl AI</h1><h2>${E(t('shortReport'))} · ${E(sid)}</h2><p>${E(t('side'))}: ${E(sideName(sideStatus(sid)))} · ${E(t(mode==='demo'?'demo':'real'))}</p><p>${C.map(c=>`${c}: ${rows(c,sid).length}`).join(' / ')} · ${E(t('cycles'))}</p><h3>${E(t('gpsTitle'))}</h3>${r.length?r.map(x=>`<p>${E(cond(x.i))}: ${num(x.b.m)} → ${num(x.a.m)}; Δ ${signed(x.d)}°; ${E(x.label)} (n=${x.b.n}/${x.a.n})</p>`).join(''):`<p>${E(t('gpsMissing'))}</p>`}<p>${E(t('gpsHint'))}</p><h3>${E(t('important'))}</h3>${a.length?a.map(x=>`<p>${E(label(x.k,x.h))} · ${E(cond(x.i))}: ${num(x.b.m)} → ${num(x.x.m)}; Δ ${signed(x.d)}; SD: ${num(x.z)} (n=${x.b.n}/${x.x.n})</p>`).join(''):`<p>${E(t('rankEmpty'))}</p>`}<h3>${E(t('anomaly'))}: ${u.length}</h3><p>${E(t('anomalyHint'))}</p><p>${E(t('noteLabel'))}: ${E((notes[sid]||'').slice(0,250))}</p><p>${E(t('note'))}</p></div>`;document.body.insertAdjacentHTML('beforeend',html);try{window.print()}finally{$('print-report')?.remove()}}

const C=['Baseline','Verbal','VR'], colors=['#8C94A8','#6C5CE7','#0E9AA7']; let lang=localStorage.getItem('asyl-lang')==='ru'?'ru':'kk',theme=localStorage.getItem('asyl-theme')||'light',page='dash',mode='none',raw={},sets={},sid='',param='',query='',model=null,notes={},error=''; const t=k=>D[lang][k]||k, E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), $=id=>document.getElementById(id), cond=i=>t(['base','verb','vr'][i]), num=x=>Number.isFinite(x)?x.toLocaleString(lang==='kk'?'kk-KZ':'ru-RU',{maximumFractionDigits:2}):'—', pct=x=>Number.isFinite(x)?(x>0?'+':'')+Math.round(x).toLocaleString(lang==='kk'?'kk-KZ':'ru-RU')+'%':'—', avg=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:NaN, norm=s=>String(s).trim().toLowerCase().replace(/[^a-zа-яәіңғүұқөһ0-9]/g,''), valid=x=>Number.isFinite(x), sideName=x=>x==='LEFT'?t('left'):x==='RIGHT'?t('right'):t('unknown');
function parseCSV(s){s=s.replace(/^\uFEFF/,'');let a=[],r=[],v='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else if(q||v==='')q=!q;else v+=c}else if(!q&&c===';'){r.push(v.trim());v=''}else if(!q&&(c==='\n'||c==='\r')){if(c==='\r'&&s[i+1]==='\n')i++;r.push(v.trim());if(r.some(Boolean))a.push(r);r=[];v=''}else v+=c}if(q)throw Error('quotes');r.push(v.trim());if(r.some(Boolean))a.push(r);if(a.length<2||a[0].length<2)throw Error('CSV');let h=a.shift();while(h.length&&h.at(-1)===''&&a.every(r=>!r[h.length-1]))h.pop();if(h.some(x=>!x)||new Set(h.map(norm)).size!==h.length)throw Error('headers');if(a.some(r=>r.length>h.length&&r.slice(h.length).some(Boolean)))throw Error('columns');return {h,rows:a.map(r=>h.map((_,i)=>r[i]||''))}}
function numeric(x){let s=String(x??'').trim().replace(/\s/g,'').replace(',','.');return /^[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?$/i.test(s)&&Number.isFinite(Number(s))?Number(s):NaN}
function guess(h,patterns){let n=h.map(norm);for(let p of patterns){let i=n.findIndex(x=>p.test(x));if(i>=0)return i}return -1}
function mapping(o){let h=o.h;return {id:guess(h,[/^(subject|subjectid|participant|participantid|patient|patientid|id|subjectnumber|participantnumber)$/, /subject|participant|patient/]),side:guess(h,[/^(side|limb|leg|context|affectedside|studiedside)$/, /side|limb/]),cycle:guess(h,[/^(cycle|cycleid|gaitcycle|gaitcycleid|stride|strideid|cyclenumber|gaitcyclenumber)$/, /cycleid|cyclenumber/])}}
function ingest(o,m){if(m.id<0)throw Error('ID');let excluded=0, unknownSides=0;let cols=o.h.map((h,i)=>({h,i,k:norm(h)})).filter(x=>![m.id,m.side,m.cycle].includes(x.i)&&!(/^(condition|trial|trialid|trialnumber|index|row|rownumber|session|age|gender|sex|time|frame|weight|height|leglength)$/.test(x.k))&&o.rows.some(r=>valid(numeric(r[x.i]))));let group=new Map();o.rows.forEach((r,j)=>{let id=r[m.id]?.trim();if(!id||/^(nan|na|null)$/i.test(id)){excluded++;return}let s=m.side<0?'':String(r[m.side]||'').toUpperCase();if(s==='L')s='LEFT';if(s==='R')s='RIGHT';if(s&&s!=='LEFT'&&s!=='RIGHT'&&!/^(NA|NAN|NULL)$/.test(s)){unknownSides++;excluded++;return}if(s!=='LEFT'&&s!=='RIGHT')s='';let cyc=m.cycle<0?'@'+j:String(r[m.cycle]||'').trim();if(!cyc||/^(nan|na|null)$/i.test(cyc)){excluded++;return}let key=JSON.stringify([id,s,cyc]);if(!group.has(key))group.set(key,{id,s,cyc,vals:{}});let g=group.get(key);cols.forEach(c=>{let x=numeric(r[c.i]);if(valid(x))(g.vals[c.k]??=[]).push(x)})});return {rows:[...group.values()].map(g=>({...g,vals:Object.fromEntries(Object.entries(g.vals).map(([k,v])=>[k,avg(v)]))})),cols,excluded,unknownSides,assumed:m.cycle<0}}
function ids(){return [...new Set(C.flatMap(c=>(sets[c]?.rows||[]).map(r=>r.id)))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))}function cols(){return [...new Map(C.flatMap(c=>(sets[c]?.cols||[]).map(x=>[x.k,x.h]))).entries()]}function sideStatus(id){let ss=[...new Set(C.flatMap(c=>(sets[c]?.rows||[]).filter(r=>r.id===id).map(r=>r.s).filter(Boolean)))];return ss.length>1?'conflict':ss[0]||''}function rows(c,id){return (sets[c]?.rows||[]).filter(r=>r.id===id)}function stat(c,id,k){let r=rows(c,id),a=r.map(x=>x.vals[k]).filter(valid),m=avg(a);return {n:a.length,total:r.length,m,sd:a.length>1?Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/(a.length-1)):NaN}}function delta(a,b){return valid(a)&&valid(b)?b-a:NaN}function rel(a,b){return valid(a)&&valid(b)&&a!==0?(b-a)/Math.abs(a)*100:NaN}
const aliases={hipmin:['Минимальный угол бедра (°)','Ұршық буынының ең кіші бұрышы (°)'],gps:['Индекс GPS (°)','GPS индексі (°)'],kneegvs:['GVS колена (°)','Тізе GVS (°)'],anklegvs:['GVS голеностопа (°)','Тобық GVS (°)'],hipgvs:['GVS бедра (°)','Жамбас GVS (°)'],pelvisgvs:['GVS таза (°)','Жамбас белдеуі GVS (°)'],hipmoment0:['Момент перехода бедра (% цикла)','Жамбас моментінің ауысуы (цикл %)']};function label(k,h){return aliases[k]?.[lang==='ru'?0:1]||h||k}function pick(){let a=ids(),b=cols();if(!a.includes(sid))sid=completeIds()[0]||a[0]||'';if(!b.some(x=>x[0]===param))param=gpsKey()||b[0]?.[0]||''}
function demo(){mode='demo';raw={};sets={};model=null;notes={};for(let i=0;i<3;i++){let s='Subject;Side;Cycle;Hip_min;GPS;Knee_GVS;Ankle_GVS;Hip_GVS;Pelvis_GVS;HipMoment0\n';for(let p=1;p<=8;p++)for(let j=1;j<=12;j++){let n=Math.sin(p*2.3+j*1.9+i*.7),v=[9+p*.8-i*2+n,13+p*.3+i*.15+n*.8,11+p*.4+i*.9+n,8+p*.3-i*.2+n*.7,10+p*.3-i*1.1+n*.6,6+p*.2+i*.4+n*.5,43+p*.4+i*2+n];s+=[`DEMO-${String(p).padStart(2,'0')}`,p%2?'LEFT':'RIGHT',j,...v.map((x,k)=>p===2&&j===3&&k===2&&i===1?'NaN':x.toFixed(3).replace('.',','))].join(';')+'\n'}let o=parseCSV(s);o.name='SYNTHETIC_'+C[i]+'.csv';o.map=mapping(o);raw[C[i]]=o;sets[C[i]]=ingest(o,o.map)}sid='';param='';query='';error='';pick();page='dash';render()}
const ORIGINAL={Baseline:{id:165961,md5:'5e8ccd07bba4cdcb0039fc2fe3bc136d'},Verbal:{id:165958,md5:'179587dd365b050dcfec5aa1611a9e74'},VR:{id:165960,md5:'1d8d64e99bffb1fe252b049c36547455'}};
function md5(bytes){let n=bytes.length,l=Math.ceil((n+9)/64)*64,b=new Uint8Array(l);b.set(bytes);b[n]=128;let v=new DataView(b.buffer);v.setUint32(l-8,(n*8)>>>0,true);v.setUint32(l-4,Math.floor(n/536870912),true);let a0=0x67452301,b0=0xefcdab89,c0=0x98badcfe,d0=0x10325476,S=[7,12,17,22,5,9,14,20,4,11,16,23,6,10,15,21];for(let off=0;off<l;off+=64){let a=a0,b=b0,c=c0,d=d0;for(let i=0;i<64;i++){let f,g;if(i<16){f=(b&c)|(~b&d);g=i}else if(i<32){f=(d&b)|(~d&c);g=(5*i+1)%16}else if(i<48){f=b^c^d;g=(3*i+5)%16}else{f=c^(b|~d);g=(7*i)%16}let z=(a+f+Math.floor(Math.abs(Math.sin(i+1))*4294967296)+v.getUint32(off+g*4,true))|0,k=S[Math.floor(i/16)*4+i%4];[a,b,c,d]=[d,(b+((z<<k)|(z>>>(32-k))))|0,b,c]}a0=(a0+a)|0;b0=(b0+b)|0;c0=(c0+c)|0;d0=(d0+d)|0}return [a0,b0,c0,d0].flatMap(x=>[0,8,16,24].map(k=>((x>>>k)&255).toString(16).padStart(2,'0'))).join('')}
function hashStatus(c){return raw[c]?.hash? t(raw[c].hash===ORIGINAL[c].md5?'verified':'notVerified'):t('noHash')}
async function batchLoad(files){let a=[...files], found=C.map(c=>a.filter(f=>new RegExp('(?:^|[_ -])'+c+'(?:[_. (\u002d]|$)','i').test(f.name)));if(a.length!==3||found.some(f=>f.length!==1)||new Set(found.flat()).size!==3){error=t('batchError');render();return}for(let i=0;i<3;i++)await load(C[i],found[i][0]);}
function completeIds(){return ids().filter(id=>sideStatus(id)!=='conflict'&&C.every(c=>rows(c,id).length))}
function workflow(){return `<div class="steps no-print">${['data','dash','ml'].map((p,i)=>`<button data-step="${p}"><b>${i+1}</b><span>${E(t('step'+(i+1)))}</span></button>`).join('')}</div>`}
function downloadJSON(){if(!model)return;let out={source:mode,files:Object.fromEntries(C.map(c=>[c,{name:raw[c]?.name,md5:raw[c]?.hash||null,publishedMatch:raw[c]?.hash===ORIGINAL[c].md5}])),method:'Nearest centroid; LOSO; train-only scaling and mean imputation',classes:C,participants:model.folds,observations:model.total,accuracy:model.acc,balancedAccuracy:model.bal,confusionMatrix:model.cm,perClassRecall:model.cm.map((r,i)=>r[i]/r.reduce((a,b)=>a+b,0))};let url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='Asyl AI-ML-metrics.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function startReal(){if(mode!=='real'){raw={};sets={};notes={};sid='';param='';mode='real'}model=null}async function load(c,file){if(!file)return;try{if(file.size>20e6)throw Error('size');let bytes=new Uint8Array(await file.arrayBuffer());let o=parseCSV(new TextDecoder().decode(bytes));o.name=file.name;o.hash=md5(bytes);o.map=mapping(o);startReal();raw[c]=o;delete sets[c];if(o.map.id>=0)sets[c]=ingest(o,o.map);error='';pick()}catch(e){error=t('bad')+': '+file.name+' ('+e.message+')'}render()}
function option(v,txt,selected){return `<option value="${E(v)}" ${selected?'selected':''}>${E(txt)}</option>`}function opts(a,v){return a.map(([k,h])=>option(k,h,k===v)).join('')}function btn(id,k,cl=''){return `<button id="${id}" class="${cl}">${E(t(k))}</button>`}function hero(title,desc){return `<section class="hero"><div><div class="eyebrow">AI-Sana / Solveathon 2026</div><h1>${E(title)}</h1><p>${E(desc)}</p></div><svg viewBox="0 0 120 90" aria-hidden="true"><g fill="none" stroke="#bcb1ff" stroke-width="3"><path d="M3 45h20l9-20 15 42 13-49 13 39 9-12h34"/><circle cx="60" cy="18" r="5" fill="#fff"/></g></svg></section>`}function status(){return `<div class="notice">${E(t(mode==='demo'?'demo':mode==='real'?'real':'none'))}</div>`}function foot(){return `<div class="foot">${E(t('note'))}<br>${E(t('privacy'))}</div>`}function render(){document.documentElement.lang=lang;document.documentElement.dataset.theme=theme;$('lang').textContent=lang==='kk'?'RU':'KZ';$('theme').setAttribute('aria-label',t('theme'));$('theme').title=t('theme');$('nav').innerHTML=[['dash','<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>'],['data','<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>'],['ml','<path d="M4 19V5m0 14h16M8 14l4-5 4 3 4-6"/>'],['help','<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-8h.01"/>']].map(([p,i])=>`<button class="nav ${page===p?'active':''}" data-page="${p}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${i}</svg>${E(t(p))}</button>`).join('')+`<div class="sideinfo small" style="padding:18px 10px">${E(t('sub'))}<br><span class="pill">${E(t('local'))}</span></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;error='';render()});pick();$('main').innerHTML=(error?`<div class="notice error">${E(error)}</div>`:'')+({dash:dashboard,data:dataPage,ml:mlPage,help:helpPage}[page])()+foot();bind()}
function statCard(k,v,sub=''){return `<div class="card"><div class="small">${E(t(k))}</div><div class="stat">${E(v)}</div><div class="small">${E(sub)}</div></div>`}function chart(st){let vals=st.map(x=>x.m).filter(valid),lo=Math.min(0,...vals),hi=Math.max(0,...vals);if(!vals.length)return `<div class="empty">${E(t('noneval'))}</div>`;if(hi===lo)hi=lo+1;let raw=(hi-lo)/4,mag=10**Math.floor(Math.log10(raw)),step=[1,2,2.5,5,10].map(f=>f*mag).find(f=>f>=raw);hi=Math.ceil(hi*1.08/step)*step;lo=lo<0?Math.floor(lo*1.08/step)*step:0;let nt=Math.round((hi-lo)/step);let y=v=>210-(v-lo)/(hi-lo)*175,z=y(0);let lines=Array.from({length:nt+1},(_,i)=>{let v=lo+step*i;return `<line x1="60" x2="490" y1="${y(v)}" y2="${y(v)}"/><text x="52" y="${y(v)+4}" text-anchor="end">${E(num(v))}</text>`}).join('');return `<svg class="chart" viewBox="0 0 510 248" role="img" aria-label="${E(t('chart'))}">${lines}<line x1="60" x2="490" y1="${z}" y2="${z}"/>${st.map((s,i)=>{let x=95+i*145;return (valid(s.m)?`<rect x="${x}" y="${Math.min(z,y(s.m))}" width="70" height="${Math.max(1,Math.abs(y(s.m)-z))}" rx="5" fill="${colors[i]}"/><text class="v" x="${x+35}" y="${s.m>=0?y(s.m)-8:y(s.m)+14}" text-anchor="middle">${E(num(s.m))}</text>`:`<text x="${x+35}" y="${z-8}" text-anchor="middle">—</text>`)+`<text x="${x+35}" y="233" text-anchor="middle">${C[i]}</text>`}).join('')}</svg>`}
function reportItems(){let arr=[];for(let [k,h] of cols()){let b=stat(C[0],sid,k);for(let i=1;i<3;i++){let x=stat(C[i],sid,k),d=delta(b.m,x.m),z=d/b.sd;if(b.n>=3&&x.n>=3&&b.sd>0&&valid(z))arr.push({k,h,i,d,z,b,x})}}return arr.sort((a,b)=>Math.abs(b.z)-Math.abs(a.z)).slice(0,4)}function summary(){let arr=reportItems();return `<div class="card"><div class="eyebrow">Asyl AI / ${E(t('method'))}</div><h2>${E(t('important'))}</h2><p class="small">${E(t('rankHint'))}</p>${arr.length?arr.map(a=>`<div class="insight"><div><b>${E(label(a.k,a.h))}</b><br><span class="small">${E(cond(a.i))} · ${num(a.b.m)} → ${num(a.x.m)} · n=${a.b.n}/${a.x.n} · ${E(t('score'))}: ${signed(a.z)}</span></div><strong>Δ ${signed(a.d)}</strong></div>`).join(''):`<p>${E(t('rankEmpty'))}</p>`}<p class="small">${E(t('caution'))}</p></div>`}
function dashboard(){let title=hero(t('hero'),t('desc'))+workflow()+status()+`<div class="actions no-print" style="margin-bottom:15px">${btn('goData','load','primary')}${btn('sample','sample')}${btn('print','onePage')}${btn('export','export')}</div>`;if(!sid)return title+`<div class="card empty">${E(t('empty'))}</div>`;let s=sideStatus(sid),cs=cols(),st=C.map(c=>stat(c,sid,param)),h=cs.find(x=>x[0]===param)?.[1], rr=C.map(c=>rows(c,sid).length);let filt=`<div class="card filters"><label>${E(t('subject'))}<br><select id="subject">${opts(ids().map(i=>[i,i]),sid)}</select></label><label>${E(t('parameter'))}<br><select id="param">${opts(cs.map(([k,h])=>[k,label(k,h)]),param)}</select></label><span class="pill">${E(t('side'))}: ${E(s==='conflict'?t('conflict'):sideName(s))}</span></div>`;if(s==='conflict')return title+filt+`<div class="notice error">${E(t('conflict'))}</div>`;return title+filt+gpsPanel()+summary()+`<div class="grid">${statCard('participants',ids().length)}${statCard('parameters',cs.length)}${statCard('cycles',rr.reduce((a,b)=>a+b,0),rr.join(' / ')+' · '+(C.some(c=>sets[c]?.assumed)?t('assumption'):t('all3')))}</div><div class="grid two"><div class="card"><h2>${E(t('chart'))}</h2><p class="small">${E(label(param,h))} · ${E(sid)}</p><div class="mini-grid">${st.map((a,i)=>`<div class="mini"><span class="small">${E(cond(i))}</span><strong>${num(a.m)}</strong><span class="small">${i?pct(rel(st[0].m,a.m)):E(t('base'))}</span></div>`).join('')}</div>${chart(st)}<p class="small">${E(t('chartHint'))}</p><div class="legend">${C.map((c,i)=>`<span><i class="dot" style="background:${colors[i]}"></i>${E(cond(i))}</span>`).join('')}</div></div><div class="card"><h2>${E(t('coverage'))}</h2>${st.map((a,i)=>`<p>${E(cond(i))} <b>${a.n}/${a.total}</b> <span class="small">${E(t('valid'))}</span><br><span class="small">${E(t('std'))}: ${num(a.sd)} · ${E(t('delta'))}: ${i?pct(rel(st[0].m,a.m)):'—'}</span></p><div class="bar"><i style="width:${a.total?a.n/a.total*100:0}%"></i></div>`).join('')}<p class="small">${E(t('qualityHint'))}</p></div></div>${!s?`<div class="notice">${E(t('unknownSide'))}</div>`:''}${anomalyPanel()}<div class="card"><h2>${E(t('table'))}</h2><div class="small">${E(t('based'))}</div><input id="search" type="search" placeholder="${E(t('search'))}" value="${E(query)}" style="margin:10px 0;max-width:100%"><div class="table" id="table">${tableHTML()}</div></div><div class="card"><h2>${E(t('noteLabel'))}</h2><textarea id="note" rows="3" style="width:100%;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:10px" placeholder="${E(t('notep'))}">${E(notes[sid]||'')}</textarea><p class="small">${E(t('icf'))}</p></div>`}
function tableHTML(){return `<table><thead><tr><th>${E(t('parameter'))}</th>${C.map(c=>`<th>${c}<br>${E(t('mean'))} (n)</th>`).join('')}<th>Δ Verbal</th><th>Δ VR</th></tr></thead><tbody>${cols().filter(([k,h])=>!query||`${h} ${label(k,h)}`.toLowerCase().includes(query.toLowerCase())).map(([k,h])=>{let s=C.map(c=>stat(c,sid,k));return `<tr><td>${E(label(k,h))}</td>${s.map(a=>`<td>${num(a.m)} (${a.n})</td>`).join('')}${s.slice(1).map(a=>`<td>${num(delta(s[0].m,a.m))}<br><span class="small">${pct(rel(s[0].m,a.m))}</span></td>`).join('')}</tr>`}).join('')}</tbody></table>`}
function dataPage(){return hero(t('data'),t('uploadhint'))+status()+`<div class="card"><div class="actions">${btn('sample','sample')}${btn('clear','clear')}</div><label class="batch"><b>${E(t('batch'))}</b><br>${E(t('batchHint'))}<input id="batch" type="file" accept=".csv,text/csv" multiple></label><p class="small" style="margin-top:10px">${E(t('schema'))}</p><div class="grid">${C.map((c,i)=>{let o=raw[c],s=sets[c];return `<section class="upload"><h3><i class="dot" style="background:${colors[i]}"></i>${c}</h3><span class="small">${E(cond(i))}</span><input type="file" id="file${i}" accept=".csv,text/csv"><span class="small">${E(o?.name||t('none'))}</span>${o?['id','side','cycle'].map(k=>`<label>${E(t(k+'col'))}<select id="${k}${i}">${option(-1,t('ignore'),o.map[k]===-1)}${o.h.map((h,j)=>option(j,h,j===o.map[k])).join('')}</select></label>`).join('')+`<button id="apply${i}">${E(t('apply'))}</button><span class="small">${E(t('rows'))}: ${o.rows.length} · ${E(t('cycles'))}: ${s?.rows.length??'—'}<br>${E(t('badrows'))}: ${s?.excluded??'—'}${s?.assumed?'<br>'+E(t('assumption')):''}</span>`:''}</section>`}).join('')}</div><p class="small" style="margin-top:12px">${E(t('countwarn'))}<br>${E(t('raw'))}</p></div><div class="card"><h2>${E(t('sourceCheck'))}</h2><p class="small">${E(t('sourceExplain'))}</p>${C.map(c=>`<div class="quality-row"><b>${c}</b><span class="small">${E(hashStatus(c))}</span></div>`).join('')}<div class="source-links">${C.map(c=>`<a href="https://rdr.kuleuven.be/file.xhtml?fileId=${ORIGINAL[c].id}&version=1.0" target="_blank" rel="noopener">${c} ↗</a>`).join('')}</div></div><div class="card"><h2>${E(t('quality'))}</h2><p>${E(t('ready'))}: <b>${completeIds().length}</b> / ${ids().length} · ${E(t('expected'))}</p>${C.map(c=>{let s=sets[c];if(!s)return `<p>${c}: —</p>`;let total=s.rows.length*s.cols.length,available=s.rows.reduce((n,r)=>n+Object.keys(r.vals).length,0);return `<p>${c}: ${E(t('participants'))} ${new Set(s.rows.map(r=>r.id)).size} · ${E(t('missing'))}: ${total-available}/${total}</p>`}).join('')}</div>`}
function* fitEvaluateSteps(){let kk=cols().map(x=>x[0]).filter(k=>C.every(c=>sets[c]?.cols.some(x=>x.k===k)));let subjects=ids().filter(id=>sideStatus(id)!=='conflict'&&C.every(c=>rows(c,id).length&&kk.some(k=>valid(stat(c,id,k).m))));if(subjects.length<3||!kk.length)throw Error('tooFew');let data=subjects.flatMap(id=>C.map((c,y)=>({id,y,x:kk.map(k=>stat(c,id,k).m)})));let cm=Array.from({length:3},()=>[0,0,0]);let used=[];for(let id of subjects){let tr=data.filter(r=>r.id!==id),te=data.filter(r=>r.id===id);let fs=kk.map((_,j)=>{let a=tr.map(r=>r.x[j]).filter(valid),m=avg(a),sd=Math.sqrt(avg(a.map(x=>(x-m)**2)));return {j,m,sd}}).filter(f=>valid(f.sd)&&f.sd>1e-12);if(!fs.length)throw Error('tooFew');used.push(fs.length);let transform=r=>fs.map(f=>valid(r.x[f.j])?(r.x[f.j]-f.m)/f.sd:0);let vecs=tr.map(r=>({...r,z:transform(r)}));let centers=C.map((_,i)=>fs.map((f,j)=>avg(vecs.filter(r=>r.y===i).map(r=>r.z[j]))));for(let r of te){let z=transform(r),dist=centers.map(a=>a.reduce((sum,x,j)=>sum+(x-z[j])**2,0)),pred=dist.indexOf(Math.min(...dist));cm[r.y][pred]++}yield {done:used.length,total:subjects.length}}let total=data.length,acc=cm.reduce((s,r,i)=>s+r[i],0)/total,bal=avg(cm.map((r,i)=>r[i]/r.reduce((s,x)=>s+x,0)));return {cm,total,acc,bal,folds:subjects.length,features:Math.min(...used)+'–'+Math.max(...used),eligible:subjects}}
function fitEvaluate(){let g=fitEvaluateSteps(),r=g.next();while(!r.done)r=g.next();return r.value}
function mlPage(){return hero(t('mltitle'),t('mlinfo'))+status()+`<div class="card"><p>${E(t('mlwarn'))}</p><p class="small">${E(t('noleak'))}<br>${E(t('unmatched'))}</p>${btn('train','train','primary')} ${model?btn('exportML','exportML'):''}<p class="small">${E(t('baselineChance'))}</p></div>${model?`<div class="grid">${statCard('acc',num(model.acc*100)+'%')}${statCard('bal',num(model.bal*100)+'%')}${statCard('folds',model.folds)}</div><div class="card"><h2>${E(t('conf'))}</h2><div class="small">${E(t('samples'))}: ${model.total} · ${E(t('features'))}: ${E(model.features)}</div><div class="table"><table><thead><tr><th>${E(t('actual'))}</th>${C.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${model.cm.map((r,i)=>`<tr><td>${C[i]}</td>${r.map((x,j)=>`<td style="background:${i===j?'var(--soft)':'transparent'}">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3 style="margin-top:15px">${E(t('recall'))}</h3>${model.cm.map((r,i)=>`<div class="quality-row">${E(cond(i))}<b>${num(100*r[i]/r.reduce((a,b)=>a+b,0))}%</b></div>`).join('')}<p class="small">${E(mode==='demo'?t('demoML'):t('mlrisk'))}</p><details><summary>${E(t('participants'))}</summary><p>${E(model.eligible.join(', '))}</p></details></div>`:`<div class="card empty">${E(t('modelnone'))}</div>`}<div class="notice">${E(t('mlrisk'))}</div>`}
function helpPage(){return hero(t('help'),t('note'))+`<div class="card"><h2>${E(t('how'))}</h2><p>${E(t('steps'))}</p><p>${E(t('uploadhint'))}</p><p>${E(t('countwarn'))}</p></div><div class="card"><h2>${E(t('method'))}</h2><p>${E(t('based'))}</p><p>${E(t('caution'))}</p><p>${E(t('mlinfo'))}</p><p>${E(t('noleak'))}</p><p>${E(t('icf'))}</p></div><div class="card"><h2>${E(t('source'))}</h2><p>De Mulder et al. (2024). <a href="https://doi.org/10.3390/children11050524" target="_blank" rel="noopener">Children 11(5), 524</a> · <a href="https://doi.org/10.48804/JUNNWW" target="_blank" rel="noopener">KU Leuven RDR</a> (CC BY-NC-SA 4.0).</p><p>${E(t('privacy'))}</p></div>`}
function safeCell(s){s=String(s??'');if(/^[\s]*[=+@-]/.test(s)&&!valid(numeric(s)))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}function exportCSV(){if(!sid||sideStatus(sid)==='conflict')return;let r=[[t('report'),sid,t(mode==='demo'?'demo':'real')],[t('side'),sideName(sideStatus(sid))],...C.map(c=>[c,raw[c]?.name||'',raw[c]?.hash||'',hashStatus(c)]),[t('parameter'),...C.flatMap(c=>[c+' '+t('mean'),c+' '+t('valid'),c+' '+t('cycles'),c+' SD']),'Δ Verbal','Δ Verbal %','Δ VR','Δ VR %']];let f=x=>valid(x)?String(x).replace('.',','):'';for(let [k,h] of cols()){let s=C.map(c=>stat(c,sid,k));r.push([label(k,h),...s.flatMap(a=>[f(a.m),a.n,a.total,f(a.sd)]),f(delta(s[0].m,s[1].m)),f(rel(s[0].m,s[1].m)),f(delta(s[0].m,s[2].m)),f(rel(s[0].m,s[2].m))])}r.push([t('important')],...reportItems().map(x=>[label(x.k,x.h),C[x.i],f(x.d),f(x.z)]),[t('anomaly')],...unusual().map(x=>[x.c,label(x.k,x.h),x.cyc,f(x.value),f(x.z)]));r.push([t('noteLabel'),notes[sid]||''],[t('countwarn')],[t('note')]);let url=URL.createObjectURL(new Blob(['\uFEFF'+r.map(x=>x.map(safeCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='Asyl-AI-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){let on=(id,fn)=>{if($(id))$(id).onclick=fn};on('sample',demo);document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{page=b.dataset.step;error='';render()});if($('batch'))$('batch').onchange=e=>batchLoad(e.target.files);on('exportML',downloadJSON);on('goData',()=>{page='data';render()});on('clear',()=>{raw={};sets={};mode='none';sid='';param='';query='';model=null;notes={};error='';render()});on('print',()=>{if(sid&&sideStatus(sid)!=='conflict')shortReport()});on('export',exportCSV);if($('print'))$('print').disabled=$('export').disabled=!sid||sideStatus(sid)==='conflict';if($('subject'))$('subject').onchange=e=>{sid=e.target.value;render()};if($('param'))$('param').onchange=e=>{param=e.target.value;render()};if($('search'))$('search').oninput=e=>{query=e.target.value;$('table').innerHTML=tableHTML()};if($('note'))$('note').oninput=e=>{notes[sid]=e.target.value};C.forEach((c,i)=>{if($('file'+i))$('file'+i).onchange=e=>load(c,e.target.files[0]);on('apply'+i,()=>{let o=raw[c],m=Object.fromEntries(['id','side','cycle'].map(k=>[k,Number($(k+i).value)]));if(m.id<0||new Set(Object.values(m).filter(x=>x>=0)).size!==Object.values(m).filter(x=>x>=0).length){error=t('noid')+' / '+t('schema');render();return}try{sets[c]=ingest(o,m);o.map=m;model=null;error='';pick()}catch(e){error=t('bad')}render()})});on('train',()=>{try{model=fitEvaluate();error=''}catch(e){model=null;error=t('tooFew')}render()})}

