function loadStudy(){mode='real';raw={};sets={};notes={};model=null;for(let c of C){let o=parseCSV(STUDY[c].csv);o.name=STUDY[c].name;o.hash=STUDY[c].hash;o.map=mapping(o);raw[c]=o;sets[c]=ingest(o,o.map)}sid='';param='';query='';error='';page='dash';pick();render()}
