function tradePanel(){let ks=['gvsasagp','gvsasagh','gvsasagk','gvsasaga'].filter(k=>cols().some(x=>x[0]===k));if(!ks.length)return '';return `<section class="card wide-section"><h2>${E(t('tradeTitle'))}</h2>${C.slice(1).map((c,i)=>{let g=gpsResults().find(x=>x.i===i+1);let diffs=ks.map(k=>[k,delta(stat(C[0],sid,k).m,stat(c,sid,k).m)]);let conflict=g&&valid(g.d)&&diffs.some(([k,d])=>valid(d)&&d*g.d<0);return `<h3>${c}</h3>${diffs.map(([k,d])=>`<div class="quality-row"><span>${E(label(k))}</span><b>${E(signed(d))}° ${valid(d)&&d!==0?' · '+E(t(d<0?'tradeCloser':'tradeFarther')):''}</b></div>`).join('')}<p class="small">${E(t(conflict?'tradeWarning':'tradeNeutral'))}</p>`}).join('')}</section>`}
